mapper.select:
SELECT FIN_OPEN_PLAN.CASH_ID cashId, FIN_OPEN_PLAN.OPEN_TYPE openType, OPEN_DATE_STR openDateStr, FIN_OPEN_PLAN.OPEN_DATE_END openDateEnd, OPEN_VDATE openVdate, OPEN_NDATE openNdate, OPEN_DATE_STR_UN openDateStrUn, OPEN_DATE_END_UN openDateEndUn, OPEN_VDATE_UN openVdateUn, OPEN_MDATE_UN openMdateUn, FIN_OPEN_PLAN.FINPROD_ID finprodId, BRANCH branch, OPEN_STATUS openStatus, SI.SEND_STATUS sendStatus, SI.SEND_REMARK sendRemark FROM FIN_OPEN_PLAN INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_OPEN_PLAN.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName} LEFT JOIN INF_FIN_OPEN_PLAN SI ON FIN_OPEN_PLAN.CASH_ID = SI.CASH_ID AND FIN_OPEN_PLAN.OPEN_TYPE = SI.OPEN_TYPE AND FIN_OPEN_PLAN.OPEN_DATE_END = SI.OPEN_DATE_END WHERE FIN_OPEN_PLAN.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and FIN_OPEN_PLAN.OPEN_TYPE = decode(FIN_OPEN_PLAN.OPEN_TYPE, #{openType03}, #{openType03}, #{scheduletype})
AND NVL(SI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
ORDER BY OPEN_DATE_STR ASC

SELECT
	TRADEDAY_RULE tradedayRule
FROM FIN_OPEN_RULE
WHERE
	CASH_ID = #{cashId,jdbcType=VARCHAR}
	AND OPEN_TYPE = #{RANSOM_ISSUE_MODE_03,jdbcType=VARCHAR}

    	SELECT FIN_PRODUCT.FINPROD_ID finprodId,
		       FIN_CASH_INFO.CASH_ID cashId
		 FROM FIN_PRODUCT, FIN_CASH_INFO, FIN_OPEN_RULE
		WHERE FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID
		  AND FIN_CASH_INFO.CASH_ID = FIN_OPEN_RULE.CASH_ID
		  AND FIN_CASH_INFO.CASH_TYPE_1 = #{CASH_TYPE1_01}
		  AND FIN_CASH_INFO.CASH_TYPE_2 = #{CASH_TYPE2_C01}
		  AND FIN_PRODUCT.P_FINPROD_ID = #{pfinprodId}
		  AND FIN_OPEN_RULE.OPEN_TYPE = #{openType}

SELECT DISTINCT FIN_PRODUCT.FINPROD_ID id, FIN_PRODUCT.FINPROD_MARKET_ID ||':'|| FIN_PRODUCT.FINPROD_ABBR text, FIN_PRODUCT.FINPROD_MARKET_ID || ',' || FIN_PRODUCT_ADD.DEAL_MODE object, FIN_PRODUCT.VDATE col FROM FIN_PRODUCT, PTL_MANAGE_OBJ, PTL_PORTFOLIO_AUTHORITY, FIN_PRODUCT_ADD
FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2} AND PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID AND PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and FIN_PRODUCT.OPERATION_TYPE = #{operationType}
AND (FIN_PRODUCT.FINPROD_ID like concat(concat('%', #{search,jdbcType=VARCHAR}),'%') OR FIN_PRODUCT.FINPROD_ABBR like concat(concat('%', #{search,jdbcType=VARCHAR}),'%'))
